from pathlib import Path
p=Path("runtime/src/builtin_number.c")
s=p.read_text()
a=s.index('/**\n * Number::toString in a radix')
b=s.index('static MalValue mal_builtin_number_prototype_to_string(',a)
s=s[:a]+'static MalString *mal_builtin_number_small_integer_radix_string(\n    MalHeap *heap,\n    f64 number,\n    i32 radix\n) {\n    static const char digits[] = "0123456789abcdefghijklmnopqrstuvwxyz";\n    bool negative = number < 0.0;\n    u64 magnitude = (u64) (negative ? -number : number);\n    byte reversed[64];\n    usize length = 0;\n    do {\n        reversed[length++] = (byte) digits[magnitude % (u32) radix];\n        magnitude /= (u32) radix;\n    } while (magnitude != 0);\n\n    byte buffer[65];\n    usize write = 0;\n    if (negative) buffer[write++] = \'-\';\n    for (usize i = 0; i < length; i++) {\n        buffer[write++] = reversed[length - i - 1];\n    }\n    return mal_string_new_ascii(heap, buffer, write);\n}\n\n/**\n * Number::toString in a radix 2..36 for a finite value. Safe integral values\n * use exact integer division; the general fractional path retains repeated\n * floating-point division/multiplication.\n */\nstatic MalString *mal_builtin_number_radix_string(\n    MalHeap *heap,\n    f64 number,\n    i32 radix\n) {\n    if (number >= -9007199254740992.0 && number <= 9007199254740992.0 &&\n        trunc(number) == number) {\n        return mal_builtin_number_small_integer_radix_string(heap, number, radix);\n    }\n\n    static const char digits[] = "0123456789abcdefghijklmnopqrstuvwxyz";\n    bool negative = number < 0;\n    if (negative) {\n        number = -number;\n    }\n\n    f64 integer = floor(number);\n    f64 fraction = number - integer;\n    byte buffer[1200];\n    usize length = 0;\n    if (negative) {\n        buffer[length++] = \'-\';\n    }\n\n    byte int_digits[64];\n    usize int_length = 0;\n    if (integer == 0) {\n        int_digits[int_length++] = \'0\';\n    } else {\n        while (integer >= 1 && int_length < sizeof(int_digits)) {\n            f64 quotient = floor(integer / radix);\n            i32 digit = (i32) (integer - quotient * radix);\n            int_digits[int_length++] = (byte) digits[digit];\n            integer = quotient;\n        }\n    }\n    for (usize i = 0; i < int_length; i++) {\n        buffer[length++] = int_digits[int_length - 1 - i];\n    }\n\n    if (fraction > 0) {\n        buffer[length++] = \'.\';\n        i32 max_fraction = 1100;\n        while (fraction > 0 && max_fraction-- > 0 && length < sizeof(buffer) - 1) {\n            fraction *= radix;\n            i32 digit = (i32) floor(fraction);\n            if (digit >= radix) {\n                digit = radix - 1;\n            }\n            buffer[length++] = (byte) digits[digit];\n            fraction -= digit;\n        }\n    }\n\n    return mal_string_new_ascii(heap, buffer, length);\n}\n\n'+s[b:]
p.write_text(s)
